@router.post("/predict", response_model=bool)
async def predict(payload: PredictRequest) -> bool:
    try:
        service = ModerationService()
        return service.predict(payload)
    except BusinessLogicError as e:
        raise HTTPException(status_code=500, detail=str(e))

class ModerationService:
    def predict(self, req: PredictRequest) -> bool:
        """
        True есть нарушение
        False нарушений нет
        """

        if req.is_verified_seller:
            return False

        if req.images_qty > 0:
            return False

        return True

def test_predict_validation_errors(payload: dict) -> None:
    resp = client.post("/predict", json=payload)
    assert resp.status_code == 422
